edits.sketch:
c_predicate     := 'pc.build_status = ''deployed''';
c_predicate_new := 'COALESCE(pc.build_status, ''pending'') <> ''removed''';

IF (length(v_q)-length(replace(v_q,c_predicate,'')))/length(c_predicate) <> 1 THEN
    RAISE EXCEPTION '574: anchor does not occur exactly once — another lane has edited this agent';
END IF;
IF position('target_not_dispatchable' in v_q) > 0 THEN
    RAISE EXCEPTION '574: already applied';
END IF;
PERFORM snapshot_agent('required-fields-missing-handler'::text, '574: ...'::text);

-- tomb CTE: POSITIVE evidence that a component was retired, vs merely not found
c_tomb := 'tomb AS (SELECT EXISTS (SELECT 1 FROM page_components pc2 JOIN pg ON pc2.page_id = pg.id '
          'CROSS JOIN item WHERE COALESCE(pc2.build_status, ''pending'') = ''removed'' '
          'AND COALESCE(pc2.slot_name, '''') = COALESCE(item.spec->>''slot_name'', '''')) AS retired), ';

-- stale now needs positive evidence; the residue routes to a PARK, not a close
c_case_new := 'WHEN (SELECT count(*) FROM pg) = 0 '
    'OR COALESCE((SELECT locked FROM comp), false) '
    'OR ((SELECT count(*) FROM comp) = 0 AND (SELECT retired FROM tomb)) THEN ''stale'' '
    'WHEN (SELECT n_still_empty FROM fs) = 0 THEN ''resolved'' '
    'WHEN (SELECT count(*) FROM comp) = 0 '
    'OR COALESCE((SELECT bs FROM comp), '''') <> ''deployed'' THEN ''target_not_dispatchable''';

v_new_q := replace(v_q, c_predicate, c_predicate_new);
v_new_q := replace(v_new_q, c_comp_cols, c_comp_cols || ', COALESCE(pc.build_status, ''pending'') AS bs');
v_new_q := replace(v_new_q, c_fx_anchor, c_tomb || c_fx_anchor);
v_new_q := replace(v_new_q, c_case_arm,  c_case_new);
v_new_q := replace(v_new_q, c_cid_out,   c_state_out || c_cid_out);
IF v_new_q = v_q THEN RAISE EXCEPTION '574: no-op rewrite'; END IF;

UPDATE agent_definitions SET default_config = jsonb_set(default_config,
    '{workflow,steps,classify,config,query}', to_jsonb(v_new_q), false)
 WHERE type='required-fields-missing-handler' AND is_active
   AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL;

IF position('pc.build_status = ''deployed''' in v_q) > 0 THEN
    RAISE EXCEPTION '574 VERIFY: the deployed-only predicate survives in classify'; END IF;
-- NEGATIVE CONTROL: the rest of the query must be intact
IF position('plan_src AS (' in v_q) = 0 OR position('has_open_tool_recreation' in v_q) = 0
OR position('n_asset_empty' in v_q) = 0 OR position('no_plan_unbuildable' in v_q) = 0 THEN
    RAISE EXCEPTION '574 VERIFY: a pre-existing part of the classify query was lost'; END IF;
SELECT count(*) INTO v_n FROM jsonb_object_keys(v_steps);
IF v_n <> 22 THEN RAISE EXCEPTION '574 VERIFY: expected 22 steps, found %', v_n; END IF;
IF v_steps #>> '{route_resolved,config,else_step}' IS DISTINCT FROM 'route_not_dispatchable'
OR v_steps #>> '{route_not_dispatchable,config,else_step}' IS DISTINCT FROM 'route_owned'
OR ... (all 18 arms) THEN
    RAISE EXCEPTION '574 VERIFY: a conditional_branch arm is mis-wired'; END IF;
IF v_steps #>> '{park_not_dispatchable,config,status}' IS DISTINCT FROM 'needs_human_review'
OR ... (the other four parks) THEN
    RAISE EXCEPTION '574 VERIFY: a park arm does not park — dedup-key churn returns'; END IF;

IF position('target_not_dispatchable' in v_q) = 0 THEN
    RAISE EXCEPTION '574 ROLLBACK: 574 is not applied — nothing to undo'; END IF;
v_q := replace(v_q, c_state_out, '');
v_q := replace(v_q, c_case_new, c_case_arm);
v_q := replace(v_q, c_tomb, '');
v_q := replace(v_q, c_comp_cols_new, c_comp_cols);
v_q := replace(v_q, c_predicate_new, c_predicate);
IF position('target_not_dispatchable' in v_q) > 0 OR position('tomb AS (' in v_q) > 0
OR position('pc.build_status = ''deployed''' in v_q) = 0 THEN
    RAISE EXCEPTION '574 ROLLBACK: the reverse rewrite was partial — do NOT commit'; END IF;
UPDATE agent_definitions SET default_config = jsonb_set(
    (default_config #- '{workflow,steps,route_not_dispatchable}')
                    #- '{workflow,steps,park_not_dispatchable}',
    '{workflow,steps,classify,config,query}', to_jsonb(v_q), false) WHERE ...;
-- then re-join: route_resolved.else_step -> 'route_owned', restore both evidence strings
IF v_steps #>> '{route_resolved,config,else_step}' IS DISTINCT FROM 'route_owned' THEN
    RAISE EXCEPTION '574 ROLLBACK: the else-cascade was not re-joined'; END IF;
